import React from 'react';
import styles from './MainPage.module.css';

const MainPage = () => {
  return (
    <div className={styles.page}>
      <h1 className={styles.title}>Movie List</h1>
      <div className={styles.section}>Movie List Content</div>

      <h2 className={styles.subtitle}>Metadata Editor</h2>
      <form className={styles.form}>Metadata Form</form>

      <section className={styles.section}>Actors</section>
      <section className={styles.section}>Categories</section>

      <div className={styles.selector}>Category Selector</div>
    </div>
  );
};

export default MainPage;
